using System;using System.Linq;using System.Windows.Forms;using BeamScheduleFormatter;
class EarthquakeSiteTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}
 const string Hazards="{\"success\":true,\"message\":\"ok\",\"data\":{\"activeFault\":{\"direction\":\"west\",\"distance\":\"9.3\",\"units\":\"km\",\"fault_name\":\"Valley Fault System\",\"segment_name\":\"West Valley Fault\",\"longitude\":121.0696642800001,\"latitude\":14.584540608000054,\"nearest_active_fault\":\"Approximately 9.3 km west of the Valley Fault System: West Valley Fault\",\"assessment\":\"Safe\",\"datemapped\":2013},\"groundRupture\":{\"assessment\":\"Safe\"},\"groundShaking\":{\"assessment\":\"Prone; Intensity VIII\",\"explanation\":[\"All sites may be affected\"]},\"liquefaction\":{\"assessment\":\"High Potential\"},\"location\":{\"name\":\"City of Manila - Quiapo, NCR\"}}}";
 const string Usgs="{\"type\":\"FeatureCollection\",\"features\":[{\"type\":\"Feature\",\"properties\":{\"mag\":7.7,\"place\":\"4 km E of Macapsing, Philippines\",\"time\":648113194610,\"magType\":\"ms\"},\"geometry\":{\"type\":\"Point\",\"coordinates\":[121.172,15.679,25.1]},\"id\":\"a\"},{\"type\":\"Feature\",\"properties\":{\"mag\":5.6,\"place\":\"near \\u00f1 site\",\"time\":1000000000000,\"magType\":\"mww\"},\"geometry\":{\"type\":\"Point\",\"coordinates\":[120.9842,14.6995,10]},\"id\":\"b\"}]}";
 [STAThread]static void Main(){
  var f=EarthquakeSite.ReadAssessment(Hazards);Check(f.FaultName=="Valley Fault System"&&f.Segment=="West Valley Fault"&&Math.Abs(f.DistanceKm-9.3)<1e-9&&f.DateMapped==2013,"HazardHunterPH active-fault fields");Check(f.GroundShaking=="Prone; Intensity VIII"&&f.Liquefaction=="High Potential"&&f.Location.StartsWith("City of Manila"),"ground shaking, liquefaction and location");
  bool failed=false;try{EarthquakeSite.ReadAssessment("{\"success\":false,\"message\":\"Unauthenticated.\"}");}catch(Exception ex){failed=ex.Message.Contains("Unauthenticated");}Check(failed,"a refused request is reported with the server message");
  var q=EarthquakeSite.ReadUsgs(Usgs,14.5995,120.9842);Check(q.Count==2&&q[0].Magnitude==7.7&&q[0].TimeUtc.Year==1990&&q[0].TimeUtc.Month==7,"USGS events, largest first (16 July 1990 M7.7)");Check(Math.Abs(q[1].DistanceKm-11.12)<.05&&q[1].Place.Contains("ñ"),"distance from the site and unicode place names");
  Check(Math.Abs(EarthquakeSite.Haversine(14.5995,120.9842,15.5995,120.9842)-111.19)<.05,"haversine distance");
  Check(EarthquakeSite.SourceType(7.2,5)=="A"&&EarthquakeSite.SourceType(7.0,4.9)=="B"&&EarthquakeSite.SourceType(6.4,2)=="C"&&EarthquakeSite.SourceType(6.4,2.1)=="B"&&EarthquakeSite.SourceType(6.7,1)=="B"&&EarthquakeSite.SourceType(double.NaN,5)=="","Table 208-3 seismic source types");
  Check(EarthquakeSite.Suggested("Philippine Fault Zone")!=null&&EarthquakeSite.Suggested("Valley Fault System").Mmax==7.2&&EarthquakeSite.Suggested("Lubang Fault")==null,"suggested parameters only for the known systems");
  bool bad=false;try{EarthquakeSite.ValidateCoordinates(35,139);}catch{bad=true;}Check(bad,"coordinates outside the Philippines are refused");
  AccessCodes.Granted=true;using(var form=new RsaCurveForm()){var t=typeof(RsaCurveForm);var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;t.GetField("fault",flags).SetValue(form,f);t.GetField("quakes",flags).SetValue(form,q);
   var inputs=(System.Collections.Generic.Dictionary<string,Control>)typeof(DesignSheetForm).GetField("Inputs",flags).GetValue(form);inputs["Latitude"].Text="14.5995";inputs["Longitude"].Text="120.9842";inputs["Distance"].Text="9.3";inputs["Mmax"].Text="7.2";inputs["SlipRate"].Text="5";
   Check(((ComboBox)inputs["Source"]).Text=="A","source type copied to the spectrum inputs");inputs["Mmax"].Text="";inputs["RuptureLength"].Text="50";Check(inputs["Mmax"].Text=="7.05","Mmax from the rupture length L (5.08 + 1.16 log10 50)");inputs["Mmax"].Text="7.2";string report=form.CurrentReport();Check(report.Contains("Valley Fault System: West Valley Fault")&&report.Contains("Type A")&&report.Contains("USGS")&&report.Contains("HazardHunterPH"),"report lists the fault, source type and history with sources");
   string xml=form.Snapshot();using(var again=new RsaCurveForm()){again.Restore(xml);var f2=(FaultSite)t.GetField("fault",flags).GetValue(again);var q2=(System.Collections.Generic.List<QuakeEvent>)t.GetField("quakes",flags).GetValue(again);Check(f2!=null&&f2.FaultName=="Valley Fault System"&&Math.Abs(f2.DistanceKm-9.3)<1e-9&&q2.Count==2&&q2[0].Magnitude==7.7,"look-up results are saved with the sheet");}}
  /* fault length and Mmax from the traces (Wells and Coppersmith 1994) and the source type with an unknown slip rate */
  Check(Math.Abs(FaultTraces.Mmax(50)-7.05)<0.01,"Mmax = 5.08 + 1.16 log10(50) = 7.05");Check(FaultTraces.All.Count>100&&FaultTraces.Coast.Count>50,"fault traces and coastline data load");
  var est=FaultTraces.ForSite(18.36,121.64);Check(est!=null&&est.LengthKm>0&&Math.Abs(est.Mmax-FaultTraces.Mmax(est.LengthKm))<1e-9&&est.Basis.Contains("Wells and Coppersmith"),"nearest trace near Aparri measured with Mmax from its length");
  var vf=FaultTraces.ForSite(14.5995,120.9842,"West Valley Fault","Valley Fault System");Check(vf!=null&&vf.FromHazardHunter&&vf.DistanceKm<30,"the HazardHunterPH fault is found in the traces");
  Check(FaultTraces.ForSite(18.1,122.0,"Dummon River Fault System")==null,"a HazardHunterPH fault not in the traces gets no other fault's length");
  Check(FaultTraces.Sensitivity(7.05,double.NaN).Contains("B to A")&&FaultTraces.Sensitivity(7.6,double.NaN).Contains("Type A holds"),"source type checked at Mmax +/- 0.28");
  var two=FaultTraces.All.Where(t=>t.Name=="West Valley Fault"||t.Name=="East Valley Fault").ToList();var both=FaultTraces.Measure(two,14.5995,120.9842,"picked on the map");Check(Math.Abs(both.LengthKm-two.Sum(t=>t.LengthKm))<1e-9&&both.Name.Contains(" + ")&&both.Basis.Contains("77 earthquakes"),"picked parts are measured together");
  /* a synthetic PHIVOLCS-style map tile: a dashed red fault, a legend sample and a filled red symbol */
  using(var bmp=new System.Drawing.Bitmap(1000,1000)){using(var g=System.Drawing.Graphics.FromImage(bmp)){g.Clear(System.Drawing.Color.White);using(var pen=new System.Drawing.Pen(System.Drawing.Color.FromArgb(254,0,0),3f)){/* dashes 15 px (1.6 km), gaps 9 px (1 km), as on the PHIVOLCS map */pen.DashPattern=new float[]{5f,3f};g.DrawLine(pen,100,100,900,700);}
    using(var solid=new System.Drawing.Pen(System.Drawing.Color.FromArgb(254,0,0),3f))g.DrawLine(solid,100,950,160,950);g.FillEllipse(System.Drawing.Brushes.Red,700,850,50,50);}
   var tiles=new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<System.Drawing.RectangleF,System.Drawing.Image>>{new System.Collections.Generic.KeyValuePair<System.Drawing.RectangleF,System.Drawing.Image>(System.Drawing.RectangleF.FromLTRB(120f,16f,121f,15f),bmp)};
   var lines=KmzFaultTracer.Trace(tiles);var names=lines.Select(t=>t.Name).Distinct().ToList();double expect=FaultTraces.Km(16-0.1005,120.1005,16-0.7005,120.9005),got=lines.Sum(t=>t.LengthKm);
   Check(names.Count==1&&Math.Abs(got-expect)<0.05*expect,"the dashed red line is traced as one fault of the right length ("+got.ToString("0.0")+" of "+expect.ToString("0.0")+" km), legend sample and symbol left out");}
  string note;Check(FaultTraces.SourceType(7.2,double.NaN,out note)=="A"&&note.Contains("unknown"),"no slip rate, Mmax >= 7: Type A");Check(FaultTraces.SourceType(6.6,double.NaN,out note)=="B","no slip rate, Mmax < 7: Type B");Check(FaultTraces.SourceType(6.0,1,out note)=="C"&&FaultTraces.SourceType(7.1,6,out note)=="A"&&FaultTraces.SourceType(7.1,3,out note)=="B","Table 208-3 with a slip rate");
  Console.WriteLine("PASS: "+checks+" earthquake site, fault source type and history checks");}
}
